import{_ as a,o as s,c as t,a5 as i}from"./chunks/framework.DrDMl0tG.js";const g=JSON.parse('{"title":"raisin::WaterFlow","description":"","frontmatter":{"title":"raisin\\\\:\\\\:WaterFlow","editLink":false,"outline":[2,3]},"headers":[],"relativePath":"api/raisin/WaterFlow.md","filePath":"api/raisin/WaterFlow.md"}'),n={name:"api/raisin/WaterFlow.md"};function l(o,e,r,h,d,p){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="page-title" tabindex="-1">raisin::WaterFlow <a class="header-anchor" href="#page-title" aria-label="Permalink to &quot;raisin::WaterFlow {#page-title}&quot;">​</a></h1><p><code>struct</code> · <code>#include &lt;rayrai/Water.hpp&gt;</code></p><p>Shallow-water simulation of a Rectangle body (<a href="./WaterBody.html#flow">WaterBody::flow</a>).</p><p>The rectangle becomes a grid of cells over the scene under it. Water flows downhill over that bed under gravity and bed friction, fills hollows, parts around whatever rises through it and runs out at open edges; its waves travel at the speed shallow water allows. The bed is the highest surface under each cell below center.z + bedCeiling, down to center.z - depth: RaiSim objects, visuals and instanced visuals that cast shadows, except foliage that sways in the wind. RaiSim bodies that are not static push the water aside and leave wakes while any part of them is below its surface. The rest of the bed is captured again when objects or visuals are added or removed, or a static RaiSim object moves or changes its body type; a visual that moves is not followed.</p><p>The simulation runs on the GPU and advances with the water clock (<a href="./RayraiWindow.html#advancewatertime">RayraiWindow::advanceWaterTime</a>); it starts with water up to center.z in every cell whose bed is lower, so a center.z below the bed starts dry. The surface is drawn from the simulated depth and velocity: the ripples, foam and caustics drift with the current, and foam forms where the water runs fast and shallow. Gerstner waves still ride on top, fading out where the water is shallow.</p><h2 id="public-attributes" tabindex="-1">Public attributes <a class="header-anchor" href="#public-attributes" aria-label="Permalink to &quot;Public attributes {#public-attributes}&quot;">​</a></h2><h3 id="enabled" tabindex="-1">enabled <a class="header-anchor" href="#enabled" aria-label="Permalink to &quot;enabled {#enabled}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> enabled</span></span></code></pre></div><p>Simulate the body, which must be a Rectangle.</p><h3 id="cellsize" tabindex="-1">cellSize <a class="header-anchor" href="#cellsize" aria-label="Permalink to &quot;cellSize {#cellsize}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cellSize</span></span></code></pre></div><p>Grid spacing, metres, [0.01, 100]; the rectangle may span at most kMaxWaterFlowCells cells per side. Smaller cells resolve narrower streams and smaller wakes at a higher cost.</p><h3 id="manningroughness" tabindex="-1">manningRoughness <a class="header-anchor" href="#manningroughness" aria-label="Permalink to &quot;manningRoughness {#manningroughness}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> manningRoughness</span></span></code></pre></div><p>Manning roughness of the bed, s/m^(1/3), [0, 0.5]: about 0.012 for concrete, 0.03 for a natural stream bed and 0.1 for a weedy one.</p><h3 id="edges" tabindex="-1">edges <a class="header-anchor" href="#edges" aria-label="Permalink to &quot;edges {#edges}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WaterFlowEdges edges</span></span></code></pre></div><p>Edges of the rectangle.</p><h3 id="bedceiling" tabindex="-1">bedCeiling <a class="header-anchor" href="#bedceiling" aria-label="Permalink to &quot;bedCeiling {#bedceiling}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bedCeiling</span></span></code></pre></div><p>Height above center.z up to which scene geometry forms the bed, metres, (0, 1e4]. A solid that reaches above it blocks the water; anything wholly above it (a bridge deck, a canopy) does not.</p><h3 id="movingbodies" tabindex="-1">movingBodies <a class="header-anchor" href="#movingbodies" aria-label="Permalink to &quot;movingBodies {#movingbodies}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> movingBodies</span></span></code></pre></div><p>Capture the RaiSim bodies that move every frame so they push the water.</p><h3 id="foamstrength" tabindex="-1">foamStrength <a class="header-anchor" href="#foamstrength" aria-label="Permalink to &quot;foamStrength {#foamstrength}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> foamStrength</span></span></code></pre></div><p>Foam where the water runs fast and shallow, [0, 1]; 0 turns it off.</p><h3 id="sources" tabindex="-1">sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;sources {#sources}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::vector</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WaterFlowSource</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sources</span></span></code></pre></div><p>At most kMaxWaterFlowSources.</p>',30)])])}const u=a(n,[["render",l]]);export{g as __pageData,u as default};
